# parse instance
with open('/app/data/instance.txt') as f:
    lines=[l.strip() for l in f if l.strip()]
J,O=map(int, lines[0].split())
idx=1
alts_map={}
for j in range(J):
    num_ops=int(lines[idx]); idx+=1
    for o in range(num_ops):
        parts=list(map(int, lines[idx].split())); idx+=1
        k=parts[0]; pairs=parts[1:]
        alts=[]
        for i in range(k):
            m=pairs[2*i]; t=pairs[2*i+1]
            alts.append((m,t))
        alts_map[(j,o)] = alts

# downtime
with open('/app/data/downtime.csv') as f:
    reader=csv.DictReader(f)
    downtime={}
    for row in reader:
        m=int(row['machine']); s=int(row['start']); e=int(row['end'])
        downtime.setdefault(m, []).append((s,e))
for m in downtime:
    downtime[m].sort()

# baseline
with open('/app/data/baseline_solution.json') as f:
    baseline=json.load(f)

baseline_map={(item['job'], item['op']): item for item in baseline['schedule']}

policy=json.load(open('/app/data/policy.json'))
freeze_enabled=policy['freeze']['enabled']
freeze_until=policy['freeze']['freeze_until']

# optional strict freeze (we'll try to see feasibility)
fixed_ops = {}
if freeze_enabled:
    for (j,o), item in baseline_map.items():
        if item['start'] < freeze_until:
            fixed_ops[(j,o)] = item

# utility

def overlaps(a_start,a_end,b_start,b_end):
    return not (a_end<=b_start or a_start>=b_end)


def earliest_start(machine, dur, ready, sched):
    t=ready
    # build blocks: scheduled intervals + downtime
    blocks = [(s,e) for (s,e,_,_) in sched]
    for ds,de in downtime.get(machine, []):
        blocks.append((ds,de))
    blocks.sort()
    while True:
        moved=False
        for s,e in blocks:
            if overlaps(t, t+dur, s, e):
                t = e
                moved=True
                break
        if not moved:
            return t

# precompute minimal remaining duration per job
min_dur = { (j,o): min(t for m,t in alts_map[(j,o)]) for j in range(J) for o in range(O)}
min_rem = {}
for j in range(J):
    for o in range(O+1):
        rem=0
        for k in range(o,O):
            rem+=min_dur[(j,k)]
        min_rem[(j,o)] = rem

prev_op={(j,o):(j,o-1) if o>0 else None for j in range(J) for o in range(O)}

machines = sorted({m for alts in alts_map.values() for m,_ in alts})


# search for feasible schedule with makespan <= bound

def find_schedule(bound, use_fixed):
    fixed = fixed_ops if use_fixed else {}

    job_next=[0]*J
    job_end=[0]*J
    machine_sched={m:[] for m in machines}
    sched={}

    # place fixed ops
    for (j,o), item in sorted(fixed.items(), key=lambda kv: kv[1]['start']):
        m=item['machine']; s=item['start']; e=item['end']; d=item['dur']
        # check duration valid
        if (m,d) not in alts_map[(j,o)]:
            return None
        # check downtime overlap
        for ds,de in downtime.get(m, []):
            if overlaps(s,e,ds,de):
                return None
        # check machine overlap
        for (s2,e2,_,_) in machine_sched[m]:
            if overlaps(s,e,s2,e2):
                return None
        # check precedence
        prev=prev_op[(j,o)]
        if prev is not None and prev in sched and sched[prev]['end']>s:
            return None
        sched[(j,o)]={'machine':m,'start':s,'end':e,'dur':d}
        machine_sched[m].append((s,e,j,o))
        machine_sched[m].sort()
        job_end[j]=max(job_end[j], e)

    # ensure predecessors of fixed are also fixed and scheduled; if not, infeasible
    for (j,o) in fixed:
        prev=prev_op[(j,o)]
        if prev is not None and prev not in sched:
            return None

    # init job_next
    for j in range(J):
        for o in range(O):
            if (j,o) not in sched:
                job_next[j]=o
                break
        else:
            job_next[j]=O

    ops_total=J*O

    best=None
    best_sched=None

    # DFS
    def dfs():
        nonlocal best, best_sched
        if len(sched)==ops_total:
            makespan=max(info['end'] for info in sched.values()) if sched else 0
            if makespan<=bound:
                best= makespan if best is None else min(best,makespan)
                best_sched=dict(sched)
                return True
            return False
        # lower bound
        lb=0
        for j in range(J):
            lb=max(lb, job_end[j]+min_rem[(j,job_next[j])])
        if lb>bound:
            return False

        # select eligible ops
        eligible=[]
        for j in range(J):
            o=job_next[j]
            if o>=O: continue
            if (j,o) in sched: continue
            prev=prev_op[(j,o)]
            if prev is None or prev in sched:
                eligible.append((j,o))
        # heuristic: sort by earliest completion
        def est(op):
            j,o=op
            ready = sched[prev_op[(j,o)]]['end'] if prev_op[(j,o)] else 0
            best_e=math.inf
            for m,d in alts_map[(j,o)]:
                s=earliest_start(m,d,ready,machine_sched[m])
                e=s+d
                if e<best_e:
                    best_e=e
            return best_e
        eligible.sort(key=est)

        for (j,o) in eligible:
            # if fixed op (shouldn't happen)
            if (j,o) in fixed:
                continue
            prev=prev_op[(j,o)]
            ready = sched[prev]['end'] if prev else 0
            # try each machine option ordered by earliest end
            options=[]
            for m,d in alts_map[(j,o)]:
                s=earliest_start(m,d,ready,machine_sched[m])
                e=s+d
                if e<=bound: # must finish within bound
                    options.append((e,s,m,d))
            options.sort()
            for e,s,m,d in options:
                # place
                sched[(j,o)]={'machine':m,'start':s,'end':e,'dur':d}
                machine_sched[m].append((s,e,j,o))
                machine_sched[m].sort()
                old_end=job_end[j]
                old_next=job_next[j]
                job_end[j]=max(job_end[j], e)
                if job_next[j]==o:
                    job_next[j]=o+1
                    while job_next[j]<O and (j,job_next[j]) in sched:
                        job_next[j]+=1
                # prune if current max end > bound
                cur_max=max(info['end'] for info in sched.values())
                if cur_max<=bound:
                    if dfs():
                        return True
                # undo
                job_next[j]=old_next
                job_end[j]=old_end
                machine_sched[m]=[t for t in machine_sched[m] if not (t[0]==s and t[1]==e and t[2]==j and t[3]==o)]
                del sched[(j,o)]
        return False

    if dfs():
        return best, best_sched
    return None

# try bounds from 30 to 39 without freeze
for b in range(30,40):
    res=find_schedule(b, use_fixed=False)
    print('bound',b,'->', 'found' if res else 'none')
    if res:
